import csv, re
with open('doc/molecule.md') as f:
    content = f.read()
carcinogenic = set()
parts = re.split(r'\n\s*\n', content)
for part in parts:
    match = re.search(r'(TR\d{3})', part)
    if match:
        mid = match.group(1)
        if 'carcinogenic' in part.lower() and ('positive' in part.lower() or 'confirmed' in part.lower()):
            carcinogenic.add(mid)
with open('csv/atom.csv') as f:
    reader = csv.DictReader(f)
    result = []
    for row in reader:
        if row['molecule_id'] in carcinogenic and row['atom_id'].endswith('_4'):
            result.append(row['element'])
for e in result:
    print(e)

